import json
d=json.load(open('outputs/analytics.json'))
def walk(o,p='\$',depth=0):
  if isinstance(o,dict):
    for k,v in o.items():
      if k in ('top_20','top20','top_20_general_procurement') or k.startswith('top'):
        print(p+'.'+k,'[list %d]'%len(v) if isinstance(v,list) else type(v).__name__); continue
      if isinstance(v,(dict,list)): 
        if isinstance(v,list) and len(v)>3: print(p+'.'+k,'[list %d]'%len(v)); continue
        walk(v,p+'.'+k,depth+1)
      else: print(p+'.'+k,'=',str(v)[:120])
  elif isinstance(o,list):
    for i,v in enumerate(o): walk(v,p+'[%d]'%i,depth+1)
walk(d)
" > /tmp/an_paths.txt; wc -l /tmp/an_paths.txt; grep -v '^\$.tests' /tmp/an_paths.txt | head -150
